// Hole die Liste der Bestellungen aus dem SAP-Ergebnis
const orders = $input.first().json.d.results;

return orders.map(order => {
    // 1. SAP-Datum in ein echtes, lesbares ISO-Datum umrechnen
    let isoDate = null;
    if (order.CreationDate) {
        const milliSeconds = parseInt(order.CreationDate.replace(/\/Date\((\d+)\)\//, '$1'));
        if (!isNaN(milliSeconds)) {
            isoDate = new Date(milliSeconds).toISOString();
        }
    }

    // 2. Den Hauptkunden (Sold-to Party = 'SP') aus den Partnern heraussuchen
    const soldToPartner = order.to_Partner?.results?.find(p => p.PartnerFunction === 'SP');
    const customerId = soldToPartner ? soldToPartner.Customer : (order.SoldToParty || "Unbekannt");

    // 3. Sichere Struktur: JEDES Feld existiert IMMER (notfalls als null)
    return {
        sales_order: order.SalesOrder || null,
        order_type: order.SalesOrderType || null,
        organization: order.SalesOrganization || null,
        customer_id: customerId || null,
        net_amount: parseFloat(order.TotalNetAmount) || 0.0, // Wichtig für ML: Immer eine Zahl
        creation_date: isoDate,
        currency: order.TransactionCurrency || null,
        created_by: order.CreatedByUser || null,
        // Falls der Status leer oder unsichtbar ist, wird er hier zu null -> Struktur bleibt exakt gleich!
        delivery_status: order.OverallTotalDeliveryStatus || null 
    };
});

let dbDate = null;

try {
  const items = $input.all();
  if (items && items.length > 0) {
    // Alle Daten sammeln und das neueste finden
    const dates = items
      .map(item => item.json.creation_date)
      .filter(d => d !== null)
      .sort();

    if (dates.length > 0) {
      dbDate = dates[dates.length - 1]; // letztes = neuestes
    }
  }
} catch (e) {}

let finalDate;
if (dbDate) {
  const nextDay = new Date(dbDate);
  nextDay.setDate(nextDay.getDate() + 1);
  finalDate = nextDay.toISOString().split('.')[0];
} else {
  finalDate = "2016-01-01T00:00:00";
}

return [{
  json: {
    sap_filter_date: finalDate
  }
}];

const response = $input.first().json;
const anomalies = response.anomalies;

if (!anomalies || anomalies.length === 0) {
  return [{
    json: {
      model: "claude-haiku-4-5-20251001",
      max_tokens: 100,
      messages: [{
        role: "user",
        content: "Antworte NUR: []"
      }]
    }
  }];
}

const liste = anomalies.map(a => 
  `Order: ${a.sales_order} | Kunde: ${a.customer_id} | Betrag: ${a.net_amount} USD | Score: ${a.anomaly_score}`
).join('\n');

return [{
  json: {
    model: "claude-haiku-4-5-20251001",
    max_tokens: 2000,
    messages: [{
      role: "user",
      content: `Du bist ein Fraud Detection Experte.
Analysiere diese ${anomalies.length} auffälligen SAP Sales Orders.

${liste}

Antworte NUR als JSON-Array, kein Text davor oder danach, keine Backticks:
[
  {
    "sales_order": "Ordernummer",
    "grund": "Ein Satz warum auffällig",
    "massnahme": "Empfohlene Maßnahme",
    "risiko_level": "KRITISCH oder VERDÄCHTIG oder PRÜFEN"
  }
]`
    }]
  }
}];

try {
  const claudeText = $input.first().json.content[0].text;
  const flaskData = $("http_request_flask").first().json.anomalies || [];

  // JSON parsen — Backticks entfernen falls Claude sie trotzdem schickt
  const cleanJson = claudeText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const result = JSON.parse(cleanJson);

  return result.map(item => {
    const flaskOrder = flaskData.find(a => String(a.sales_order) === String(item.sales_order)) || {};

    return {
      json: {
        sales_order: item.sales_order,
        customer_id: flaskOrder.customer_id || null,
        net_amount: flaskOrder.net_amount || null,
        anomaly_score: flaskOrder.anomaly_score || null,
        claude_analyse: `${item.grund} | ${item.massnahme}`,
        risiko_level: item.risiko_level
      }
    };
  });

} catch (error) {
  return [{
    json: {
      sales_order: "PARSE_ERROR",
      customer_id: null,
      net_amount: null,
      anomaly_score: null,
      claude_analyse: error.message,
      risiko_level: "PRÜFEN"
    }
  }];
}

try {
  const ordersData = $("historie_orders").all();
  const anomalienData = $("historie_anomalien").all();

  const totalOrders = ordersData.length;
  const orderDates = ordersData.map(o => o.json.creation_date).filter(d => d);
  orderDates.sort();
  const minDate = orderDates.length > 0 ? new Date(orderDates[0]) : null;
  const maxDate = orderDates.length > 0 ? new Date(orderDates[orderDates.length - 1]) : null;
  const tageSpanne = minDate && maxDate ? Math.ceil((maxDate - minDate) / (1000 * 60 * 60 * 24)) + 1 : 0;
  const ordersProTag = tageSpanne > 0 ? (totalOrders / tageSpanne).toFixed(1) : 0;

  const totalAnomalien = anomalienData.length;
  const kritisch = anomalienData.filter(a => a.json.risiko_level === 'KRITISCH').length;
  const verdaechtig = anomalienData.filter(a => a.json.risiko_level === 'VERDÄCHTIG').length;
  const pruefen = anomalienData.filter(a => a.json.risiko_level === 'PRÜFEN').length;
  const anomalieRate = totalOrders > 0 ? ((totalAnomalien / totalOrders) * 100).toFixed(2) : 0;

  const anomalieProTag = {};
  anomalienData.forEach(a => {
    const tag = a.json.detected_at ? String(a.json.detected_at).split('T')[0] : 'unbekannt';
    anomalieProTag[tag] = (anomalieProTag[tag] || 0) + 1;
  });
  const top5Tage = Object.entries(anomalieProTag).sort((a, b) => b[1] - a[1]).slice(0, 5);

  const anzahlTage = Object.keys(anomalieProTag).length || 1;
  const durchschnittProTag = totalAnomalien / anzahlTage;
  const heuteTag = new Date().toISOString().split('T')[0];
  const heuteAnzahl = anomalieProTag[heuteTag] || 0;
  const haeufung = heuteAnzahl > durchschnittProTag * 3;
  const haeufungStatus = haeufung
    ? `⚠️ HÄUFUNG! (${heuteAnzahl} heute vs Schnitt ${durchschnittProTag.toFixed(1)})`
    : `✅ Normal (${heuteAnzahl} heute, Schnitt ${durchschnittProTag.toFixed(1)})`;

  const letzteAnomalien = [...anomalienData].sort((a, b) => new Date(b.json.detected_at) - new Date(a.json.detected_at)).slice(0, 10);

  const detailRows = letzteAnomalien.map(a => {
    const j = a.json;
    const farbe = j.risiko_level === 'KRITISCH' ? '#e74c3c' : j.risiko_level === 'VERDÄCHTIG' ? '#f39c12' : '#3498db';
    return `<tr><td style="padding:8px;border-bottom:1px solid #eee;">${j.sales_order || '-'}</td><td style="padding:8px;border-bottom:1px solid #eee;">${j.customer_id || '-'}</td><td style="padding:8px;border-bottom:1px solid #eee;text-align:right;">${j.net_amount || '-'} USD</td><td style="padding:8px;border-bottom:1px solid #eee;">${j.anomaly_score || '-'}</td><td style="padding:8px;border-bottom:1px solid #eee;"><span style="background:${farbe};color:white;padding:2px 8px;border-radius:4px;">${j.risiko_level || '-'}</span></td></tr>`;
  }).join('');

  const top5Html = top5Tage.map((t, i) => `<tr><td style="padding:6px;">${i + 1}.</td><td style="padding:6px;">${t[0]}</td><td style="padding:6px;font-weight:bold;">${t[1]} Anomalien</td></tr>`).join('');

  const html = `<html><body style="font-family:Arial,sans-serif;max-width:800px;margin:auto;padding:20px;background:#f5f5f5;">
<div style="background:#c0392b;color:white;padding:20px;border-radius:8px 8px 0 0;">
<h1 style="margin:0;">🚨 SAP Fraud Detection Digest</h1>
<p style="margin:5px 0 0 0;opacity:0.9;">Generiert: ${new Date().toLocaleString('de-DE')}</p></div>
<div style="background:white;padding:20px;border-radius:0 0 8px 8px;">
<h2 style="color:#2c3e50;border-bottom:2px solid #3498db;padding-bottom:8px;">📊 Datenbestand</h2>
<table style="width:100%;"><tr><td style="padding:6px;color:#666;">Orders:</td><td style="font-weight:bold;">${totalOrders}</td></tr>
<tr><td style="padding:6px;color:#666;">Zeitraum:</td><td>${minDate ? minDate.toLocaleDateString('de-DE') : '-'} bis ${maxDate ? maxDate.toLocaleDateString('de-DE') : '-'}</td></tr>
<tr><td style="padding:6px;color:#666;">Tage:</td><td>${tageSpanne}</td></tr>
<tr><td style="padding:6px;color:#666;">Orders/Tag:</td><td>${ordersProTag}</td></tr></table>
<h2 style="color:#2c3e50;border-bottom:2px solid #e74c3c;padding-bottom:8px;margin-top:30px;">📈 Anomalie Historie</h2>
<table style="width:100%;"><tr><td style="padding:6px;color:#666;">Gesamt:</td><td style="font-weight:bold;">${totalAnomalien}</td></tr>
<tr><td style="padding:6px;color:#666;">Rate:</td><td>${anomalieRate}%</td></tr>
<tr><td style="padding:6px;color:#666;">Verteilung:</td><td><span style="background:#e74c3c;color:white;padding:2px 8px;border-radius:4px;">KRITISCH: ${kritisch}</span> <span style="background:#f39c12;color:white;padding:2px 8px;border-radius:4px;">VERDÄCHTIG: ${verdaechtig}</span> <span style="background:#3498db;color:white;padding:2px 8px;border-radius:4px;">PRÜFEN: ${pruefen}</span></td></tr></table>
<h2 style="color:#2c3e50;border-bottom:2px solid #f39c12;padding-bottom:8px;margin-top:30px;">🔥 Top 5 Anomalie Tage</h2>
<table style="width:100%;">${top5Html || '<tr><td style="color:#999;">Noch keine Daten</td></tr>'}</table>
<h2 style="color:#2c3e50;border-bottom:2px solid #27ae60;padding-bottom:8px;margin-top:30px;">🔍 Häufungscheck</h2>
<p style="font-size:16px;padding:10px;background:${haeufung ? '#ffeaa7' : '#dfe6e9'};border-radius:4px;">${haeufungStatus}</p>
<h2 style="color:#2c3e50;border-bottom:2px solid #e74c3c;padding-bottom:8px;margin-top:30px;">🚨 Letzte 10 Anomalien</h2>
<table style="width:100%;border-collapse:collapse;"><tr style="background:#34495e;color:white;"><th style="padding:8px;">Order</th><th style="padding:8px;">Kunde</th><th style="padding:8px;">Betrag</th><th style="padding:8px;">Score</th><th style="padding:8px;">Risiko</th></tr>${detailRows || '<tr><td colspan="5" style="padding:8px;color:#999;">Keine Anomalien</td></tr>'}</table>
</div><p style="color:#999;font-size:11px;text-align:center;">SAP × n8n × Isolation Forest × Claude</p></body></html>`;

  return [{
    json: {
      subject: `🚨 SAP Fraud Digest — ${totalAnomalien} Anomalien | ${new Date().toLocaleDateString('de-DE')}`,
      html: html
    }
  }];

} catch (error) {
  return [{
    json: {
      subject: `🚨 SAP Fraud Digest — Fehler | ${new Date().toLocaleDateString('de-DE')}`,
      html: `<html><body><h1>Digest Fehler</h1><p>${error.message}</p><p>${error.stack}</p></body></html>`
    }
  }];
}
